INSERT INTO tdf_sets (id,title,class_number,description,"order",created,updated) VALUES ('nx7jbq3w07s8gxl','Цилиндр, конус и шар',11,'Опросник: определения и формулы без доказательств (Атанасян 10–11, гл. IV + объёмы и комбинации тел для базового ЕГЭ)',6,'2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('l6uftwneepfpm0k','nx7jbq3w07s8gxl',0,1,'1. Цилиндр','','','','','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('yydpbj2fd39jrwt','nx7jbq3w07s8gxl',1,0,'','definition','1. Цилиндр','Какое тело называется цилиндром?','Цилиндр — тело, ограниченное [[цилиндрической поверхностью]] и [[двумя кругами]], плоскости которых [[параллельны]]. Круги называются [[основаниями]] цилиндра.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('s9hnjswz06tdy77','nx7jbq3w07s8gxl',2,0,'','property','2. Образующие цилиндра','Что называется образующими цилиндра? Каким свойством они обладают?','Образующие — отрезки образующих цилиндрической поверхности, заключённые [[между основаниями]]. Все образующие цилиндра [[параллельны]] и [[равны]] друг другу и [[перпендикулярны]] плоскостям оснований. Образованная ими часть поверхности — [[боковая поверхность]] цилиндра.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('z0o44md9y21ieoq','nx7jbq3w07s8gxl',3,0,'','definition','3. Высота, радиус и ось цилиндра','Что называется высотой, радиусом и осью цилиндра?','Высота цилиндра — [[длина образующей]], радиус цилиндра — [[радиус основания]]. Ось цилиндра — прямая, проходящая через [[центры оснований]].','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('c0inzsqyaaud284','nx7jbq3w07s8gxl',4,0,'','property','4. Цилиндр как тело вращения','Вращением какой фигуры можно получить цилиндр?','Цилиндр получается вращением [[прямоугольника]] вокруг [[одной из его сторон]]. Боковая поверхность образуется вращением [[противоположной стороны]], основания — вращением [[двух других сторон]].','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('ybkbu4rp7vz8etp','nx7jbq3w07s8gxl',5,0,'','property','5. Осевое сечение цилиндра','Что представляет собой осевое сечение цилиндра?','Осевое сечение (плоскость проходит через ось) — [[прямоугольник]]: две его стороны — [[образующие]], две другие — [[диаметры оснований]]. Его стороны равны $[[h]]$ и $[[2r]]$, площадь $S = [[2rh]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('6rsamz3s93at67y','nx7jbq3w07s8gxl',6,0,'','property','6. Сечение цилиндра плоскостью, перпендикулярной оси','Какая фигура получается в сечении цилиндра плоскостью, перпендикулярной его оси?','[[Круг]], равный [[основанию цилиндра]].','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('n1eps5h4stcs66b','nx7jbq3w07s8gxl',7,0,'','property','7. Сечение цилиндра плоскостью, параллельной оси','Какая фигура получается в сечении цилиндра плоскостью, параллельной оси и удалённой от неё на расстояние $d < r$?','[[Прямоугольник]], две противоположные стороны которого — [[образующие]] (длина $h$), а две другие — [[хорды оснований]] длиной $[[2\sqrt{r^2 - d^2}]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('p956a9kasrlk12y','nx7jbq3w07s8gxl',8,0,'','definition','8. Развёртка боковой поверхности цилиндра','Что является развёрткой боковой поверхности цилиндра? Каковы её размеры?','[[Прямоугольник]] со сторонами $[[2\pi r]]$ (длина окружности основания) и $[[h]]$ (высота цилиндра). За площадь боковой поверхности принимается [[площадь её развёртки]].','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('dned13hlq8j6e88','nx7jbq3w07s8gxl',9,0,'','formula','9. Площадь боковой поверхности цилиндра','Чему равна площадь боковой поверхности цилиндра?','Площадь боковой поверхности цилиндра равна произведению [[длины окружности основания]] на [[высоту]]: $S_{\text{бок}} = [[2\pi r h]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('n2u109emlkasbcv','nx7jbq3w07s8gxl',10,0,'','formula','10. Площадь полной поверхности цилиндра','Чему равна площадь полной поверхности цилиндра?','Это сумма площадей [[боковой поверхности]] и [[двух оснований]]: $S_{\text{полн}} = 2\pi r h + [[2\pi r^2]] = [[2\pi r (r + h)]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('7uu9ju31qzqe8gm','nx7jbq3w07s8gxl',11,0,'','formula','11. Объём цилиндра','Чему равен объём цилиндра?','Объём цилиндра равен произведению [[площади основания]] на [[высоту]]: $V = [[\pi r^2 h]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('0jsmh7tx7bfod97','nx7jbq3w07s8gxl',12,1,'2. Конус','','','','','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('acqafldmxaexuvj','nx7jbq3w07s8gxl',13,0,'','definition','12. Конус','Какое тело называется конусом?','Конус — тело, ограниченное [[конической поверхностью]] и [[кругом]] с границей $L$. Круг называется [[основанием]] конуса, вершина конической поверхности — [[вершиной]] конуса.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('bvrpp6jwre5msae','nx7jbq3w07s8gxl',14,0,'','definition','13. Образующие и высота конуса','Что называется образующими, осью и высотой конуса?','Образующие — отрезки, соединяющие [[вершину]] с точками [[окружности основания]]; все образующие конуса [[равны]]. Ось — прямая, проходящая через [[вершину]] и [[центр основания]]. Высота — отрезок оси между [[вершиной]] и [[основанием]]; она [[перпендикулярна]] плоскости основания.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('boa2z1e5czlizv4','nx7jbq3w07s8gxl',15,0,'','formula','14. Связь образующей, высоты и радиуса','Как связаны образующая, высота и радиус основания конуса?','Высота, радиус и образующая образуют [[прямоугольный треугольник]] с гипотенузой [[l]]: $l^2 = [[r^2 + h^2]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('o9pvnnz7brdeu4o','nx7jbq3w07s8gxl',16,0,'','property','15. Конус как тело вращения','Вращением какой фигуры можно получить конус?','Конус получается вращением [[прямоугольного треугольника]] вокруг [[одного из катетов]]. Боковая поверхность образуется вращением [[гипотенузы]], основание — вращением [[второго катета]].','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('fkowvvlhyz5tkyi','nx7jbq3w07s8gxl',17,0,'','property','16. Осевое сечение конуса','Что представляет собой осевое сечение конуса?','[[Равнобедренный треугольник]]: его основание — [[диаметр основания]] конуса, боковые стороны — [[образующие]]. Площадь осевого сечения $S = [[rh]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('p75zcsk982rofvn','nx7jbq3w07s8gxl',18,0,'','property','17. Сечение конуса плоскостью, перпендикулярной оси','Какая фигура получается в сечении конуса плоскостью, перпендикулярной оси? Чему равен её радиус?','[[Круг]] с центром $O_1$ [[на оси конуса]]. Его радиус во столько раз меньше радиуса основания, во сколько раз расстояние $PO_1$ от вершины до сечения меньше [[высоты]] $PO$: $r_1 = [[\dfrac{PO_1}{PO}\, r]]$. Плоскость отсекает [[конус]], подобный данному.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('kqjkh1sqp9t7a4l','nx7jbq3w07s8gxl',19,0,'','definition','18. Развёртка боковой поверхности конуса','Что является развёрткой боковой поверхности конуса?','[[Круговой сектор]], радиус которого равен [[образующей]] конуса, а длина дуги равна [[длине окружности основания]] ($2\pi r$).','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('wdhpsfiikp91smc','nx7jbq3w07s8gxl',20,0,'','formula','19. Площадь боковой поверхности конуса','Чему равна площадь боковой поверхности конуса?','Площадь боковой поверхности конуса равна произведению [[половины длины окружности основания]] на [[образующую]]: $S_{\text{бок}} = [[\pi r l]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('zd4u8tz0qnng58v','nx7jbq3w07s8gxl',21,0,'','formula','20. Площадь полной поверхности конуса','Чему равна площадь полной поверхности конуса?','Это сумма площадей [[боковой поверхности]] и [[основания]]: $S_{\text{полн}} = \pi r l + [[\pi r^2]] = [[\pi r (l + r)]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('t8j7qbytb10dlzj','nx7jbq3w07s8gxl',22,0,'','formula','21. Объём конуса','Чему равен объём конуса?','Объём конуса равен [[одной трети]] произведения площади основания на высоту: $V = [[\dfrac{1}{3}\pi r^2 h]]$. Он в [[3]] раза меньше объёма цилиндра с тем же основанием и той же высотой.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('ecm2cpajxp5gu6f','nx7jbq3w07s8gxl',23,0,'','definition','22. Усечённый конус','Какое тело называется усечённым конусом?','Плоскость, [[перпендикулярная оси]] конуса, разбивает его на две части: одна — [[конус]], другая — [[усечённый конус]]. Его основания — [[основание исходного конуса]] и [[круг, полученный в сечении]]; высота — [[отрезок, соединяющий центры оснований]].','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('xtmhfmmttw8zcs4','nx7jbq3w07s8gxl',24,0,'','formula','23. Площадь боковой поверхности усечённого конуса','Чему равна площадь боковой поверхности усечённого конуса?','$S_{\text{бок}} = [[\pi (r + r_1)\, l]]$, где $r$ и $r_1$ — [[радиусы оснований]], $l$ — [[образующая]] усечённого конуса.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('6t4hpvz2r26ja5m','nx7jbq3w07s8gxl',25,1,'3. Сфера и шар','','','','','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('nrc53j5w24hkclg','nx7jbq3w07s8gxl',26,0,'','definition','24. Сфера','Что называется сферой?','Сфера — [[поверхность]], состоящая из [[всех точек пространства]], расположенных на [[данном расстоянии]] от [[данной точки]]. Данная точка — [[центр]] сферы, данное расстояние — [[радиус]] сферы.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('cbyjivtjlu84icv','nx7jbq3w07s8gxl',27,0,'','definition','25. Диаметр сферы','Что называется диаметром сферы? Чему он равен?','Отрезок, соединяющий [[две точки сферы]] и проходящий [[через её центр]]. Диаметр равен $[[2R]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('93ap1udl7gjzor5','nx7jbq3w07s8gxl',28,0,'','definition','26. Шар','Какое тело называется шаром? Какие точки ему принадлежат?','Шар — тело, ограниченное [[сферой]]. Шар радиуса $R$ с центром $O$ содержит все точки пространства, расположенные от $O$ на расстоянии, [[не превышающем R]].','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('9ew9dt0qvpckoc9','nx7jbq3w07s8gxl',29,0,'','property','27. Сфера и шар как тела вращения','Вращением какой фигуры можно получить сферу? Шар?','Сфера получается вращением [[полуокружности]] вокруг [[её диаметра]], шар — вращением [[полукруга]] вокруг [[его диаметра]].','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('j0uqxhyp4izhdkg','nx7jbq3w07s8gxl',30,0,'','theorem','28. Взаимное расположение сферы и плоскости','Как расположены сфера и плоскость в зависимости от радиуса $R$ и расстояния $d$ от центра до плоскости?','Если $d < R$ — сфера и плоскость пересекаются по [[окружности]]; если $d = R$ — имеют [[только одну общую точку]]; если $d > R$ — [[не имеют общих точек]].','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('b1h1ysjnkda57o3','nx7jbq3w07s8gxl',31,0,'','formula','29. Сечение шара плоскостью','Какая фигура является сечением шара плоскостью? Чему равен её радиус?','Сечение шара плоскостью — [[круг]]. Его радиус $r = [[\sqrt{R^2 - d^2}]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('m3zevgeapmv2soi','nx7jbq3w07s8gxl',32,0,'','definition','30. Большой круг шара','Что называется большим кругом шара?','Сечение шара плоскостью, проходящей [[через центр]] шара. Его радиус [[равен радиусу шара]].','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('0ce1im0w88yiflb','nx7jbq3w07s8gxl',33,0,'','definition','31. Касательная плоскость к сфере','Какая плоскость называется касательной к сфере?','Плоскость, имеющая со сферой [[только одну общую точку]]; эта точка называется [[точкой касания]].','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('bqbvxie23uh29q8','nx7jbq3w07s8gxl',34,0,'','theorem','32. Свойство касательной плоскости','Каким свойством обладает касательная плоскость к сфере?','Радиус сферы, проведённый в [[точку касания]], [[перпендикулярен]] касательной плоскости. Обратно: плоскость, проходящая через конец радиуса [[перпендикулярно]] ему, — [[касательная]] к сфере.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('dpghj6x9mo15t7v','nx7jbq3w07s8gxl',35,0,'','formula','33. Площадь сферы','Чему равна площадь сферы?','$S = [[4\pi R^2]]$ — в [[4]] раза больше площади большого круга.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('fjfr45k97tuzxfu','nx7jbq3w07s8gxl',36,0,'','formula','34. Объём шара','Чему равен объём шара?','$V = [[\dfrac{4}{3}\pi R^3]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('c5b6abj2r1d00yw','nx7jbq3w07s8gxl',37,1,'4. Подобные тела','','','','','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('27m9ocyv367vozr','nx7jbq3w07s8gxl',38,0,'','property','35. Отношение площадей и объёмов подобных тел','Как изменятся площадь поверхности и объём тела, если все его линейные размеры увеличить в $k$ раз?','Площадь поверхности увеличится в $[[k^2]]$ раз, объём — в $[[k^3]]$ раз. Например, у шара с вдвое бо́льшим радиусом площадь сферы больше в [[4]] раза, объём — в [[8]] раз.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('7xfp1to254o2nz4','nx7jbq3w07s8gxl',39,1,'5. Комбинации тел (опора для задач)','','','','','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('6nk22cacewpg81x','nx7jbq3w07s8gxl',40,0,'','property','36. Цилиндр и конус с общим основанием и высотой','Как связаны объёмы цилиндра и конуса, имеющих общее основание и общую высоту?','$V_{\text{кон}} = [[\dfrac{1}{3}]]\, V_{\text{цил}}$: объём конуса в [[3]] раза меньше.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('6z1oczrnlcvwizo','nx7jbq3w07s8gxl',41,0,'','property','37. Шар, вписанный в цилиндр','Шар вписан в цилиндр (цилиндр описан около шара). Как связаны их размеры?','Радиус цилиндра [[равен радиусу шара]]: $r = R$, а высота равна [[диаметру шара]]: $h = [[2R]]$. Осевое сечение цилиндра — [[квадрат]].','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('ms9sanhmtm4to3s','nx7jbq3w07s8gxl',42,0,'','property','38. Шар, вписанный в куб','Шар вписан в куб с ребром $a$. Чему равен радиус шара?','Диаметр шара равен [[ребру куба]]: $R = [[\dfrac{a}{2}]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('4iyn8s0a67dzsde','nx7jbq3w07s8gxl',43,0,'','property','39. Куб, вписанный в шар','Куб с ребром $a$ вписан в шар (шар описан около куба). Чему равен радиус шара?','Диаметр шара равен [[диагонали куба]]: $2R = [[a\sqrt{3}]]$.','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
INSERT INTO tdf_items (id,tdf_set,"order",is_section_header,section_title,type,name,question_md,formulation_md,created,updated) VALUES ('jcks3jifba34h9g','nx7jbq3w07s8gxl',44,0,'','property','40. Цилиндр, вписанный в правильную четырёхугольную призму','Цилиндр вписан в правильную четырёхугольную призму (призма описана около цилиндра). Как связаны их размеры?','Сторона основания призмы равна [[диаметру основания цилиндра]] ($a = [[2r]]$), высоты призмы и цилиндра [[равны]].','2026-10-26 07:00:03.000Z','2026-10-26 07:00:03.000Z');
